"use client";

import { useParams } from "next/navigation";
import { motion } from "framer-motion";
import {
  ArrowLeft,
  Network,
  Building,
  Globe,
  Link2,
  Copy,
  Check,
  Download,
  FileJson,
  FileText,
  FileSpreadsheet,
  Search,
  X,
  Filter,
  Wifi,
  WifiOff,
  Shield,
  Zap,
} from "lucide-react";
import Link from "next/link";
import { useState, useMemo } from "react";
import Flag from "@/components/ui/Flag";
import { useASNData } from "@/hooks/useData";
import Skeleton from "@/components/ui/Skeleton";
import Pagination from "@/components/ui/Pagination";
import { detectIPVersion, getIPStats } from "@/lib/ipUtils";

export default function ASNDetailPage() {
  const params = useParams();
  const countryCode = params.countryCode as string;
  const asn = params.asn as string;
  const { data, loading } = useASNData(countryCode, asn);
  const [copiedIndex, setCopiedIndex] = useState<number | null>(null);
  const [downloadFormat, setDownloadFormat] = useState<"json" | "txt" | "csv">(
    "json",
  );
  const [currentPage, setCurrentPage] = useState(1);
  const [searchQuery, setSearchQuery] = useState("");
  const [filterType, setFilterType] = useState<"all" | "IPv4" | "IPv6">("all");
  const itemsPerPage = 20;

  const filteredData = useMemo(() => {
    if (!data) return [];

    let result = data;

    if (filterType !== "all") {
      result = result.filter(
        (entry) => detectIPVersion(entry.network) === filterType,
      );
    }

    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter((entry) =>
        entry.network.toLowerCase().includes(query),
      );
    }

    return result;
  }, [data, searchQuery, filterType]);

  const stats = useMemo(() => {
    if (!data) return { total: 0, ipv4: 0, ipv6: 0, unknown: 0 };
    const networks = data.map((entry) => entry.network);
    return getIPStats(networks);
  }, [data]);

  const totalPages = Math.ceil(filteredData.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const currentData = filteredData.slice(startIndex, endIndex);

  const handlePageChange = (page: number) => {
    setCurrentPage(page);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const handleSearch = (value: string) => {
    setSearchQuery(value);
    setCurrentPage(1);
  };

  const clearSearch = () => {
    setSearchQuery("");
    setCurrentPage(1);
  };

  const handleFilterChange = (type: "all" | "IPv4" | "IPv6") => {
    setFilterType(type);
    setCurrentPage(1);
  };

  const copyToClipboard = async (text: string, index: number) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopiedIndex(index);
      setTimeout(() => setCopiedIndex(null), 2000);
    } catch (err) {
      console.error("Failed to copy:", err);
    }
  };

  const downloadNetworks = () => {
    if (!data) return;

    const networks = filteredData.map((entry) => entry.network);
    let content = "";
    let filename = `AS${asn}_networks`;
    let mimeType = "";

    if (filterType !== "all") {
      filename += `_${filterType.toLowerCase()}`;
    }
    if (searchQuery) {
      filename += `_filtered`;
    }

    switch (downloadFormat) {
      case "json":
        content = JSON.stringify(
          {
            asn: asn,
            country: countryCode,
            organization: data[0]?.org || "",
            name: data[0]?.name || "",
            total_networks: filteredData.length,
            filter: {
              type: filterType,
              search: searchQuery || null,
            },
            networks: networks,
          },
          null,
          2,
        );
        filename += ".json";
        mimeType = "application/json";
        break;

      case "txt":
        content = networks.join("\n");
        filename += ".txt";
        mimeType = "text/plain";
        break;

      case "csv":
        content =
          "network,ip_version\n" +
          networks.map((n) => `${n},${detectIPVersion(n)}`).join("\n");
        filename += ".csv";
        mimeType = "text/csv";
        break;
    }

    const blob = new Blob([content], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  if (loading) {
    return (
      <div className="space-y-6">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="h-40 w-full" variant="card" />
        <Skeleton className="h-12 w-full" />
        <div className="grid grid-cols-1 gap-4">
          {[...Array(4)].map((_, i) => (
            <Skeleton key={i} className="h-16 w-full" />
          ))}
        </div>
      </div>
    );
  }

  if (!data || data.length === 0) {
    return (
      <div className="text-center py-16">
        <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-[rgba(34,229,122,.08)] border border-[rgba(34,229,122,.1)] mb-4">
          <Network size={28} className="text-[#4f6459]" />
        </div>
        <p className="text-[#93a79d] font-mono">No data found for AS{asn}</p>
        <Link
          href={`/asn/${countryCode}`}
          className="inline-flex items-center gap-2 text-[#22e57a] hover:text-[#5cffa5] mt-4 transition-colors font-mono text-sm"
        >
          <ArrowLeft size={14} />
          Back to {countryCode.toUpperCase()} ASNs
        </Link>
      </div>
    );
  }

  const firstEntry = data[0];
  const totalNetworks = data.length;
  const filteredCount = filteredData.length;

  return (
    <div className="space-y-6">
      {/* Back Button */}
      <Link
        href={`/asn/${countryCode}`}
        className="inline-flex items-center gap-2 text-[#6f8a7d] hover:text-[#c6d2ca] transition-colors font-mono text-sm"
      >
        <ArrowLeft size={16} />
        Back to {countryCode.toUpperCase()} ASNs
      </Link>

      {/* Header Card */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="bg-[#070b09]/80 backdrop-blur-sm border border-[rgba(34,229,122,.12)] rounded-xl p-6"
      >
        <div className="flex flex-col lg:flex-row lg:items-center gap-4">
          <div className="flex items-center gap-4">
            <div className="flex-shrink-0 w-16 h-16 bg-[rgba(34,229,122,.08)] rounded-xl flex items-center justify-center border border-[rgba(34,229,122,.15)]">
              <Network size={32} className="text-[#22e57a]" />
            </div>
            <div>
              <div className="flex items-center gap-3">
                <h1 className="text-3xl font-bold font-mono text-[#f2fff8]">
                  AS{asn}
                </h1>
                {firstEntry?.name && (
                  <span className="text-sm text-[#93a79d] font-mono bg-[#0a100d] px-3 py-1 rounded-md border border-[rgba(34,229,122,.06)]">
                    {firstEntry.name}
                  </span>
                )}
              </div>
              <div className="flex flex-wrap items-center gap-4 text-sm mt-1.5">
                <span className="flex items-center gap-1.5 text-[#6f8a7d]">
                  <Globe size={14} />
                  {totalNetworks.toLocaleString()} networks
                </span>
                <span className="flex items-center gap-1.5 text-[#22e57a]">
                  <Wifi size={14} />
                  IPv4: {stats.ipv4}
                </span>
                <span className="flex items-center gap-1.5 text-[#5c8aff]">
                  <WifiOff size={14} />
                  IPv6: {stats.ipv6}
                </span>
                {searchQuery && (
                  <span className="text-[#22e57a] font-mono text-xs">
                    {filteredCount.toLocaleString()} filtered
                  </span>
                )}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-3 lg:ml-auto">
            <Flag countryCode={countryCode} size={36} variant="rounded" />
            <span className="text-sm font-mono text-[#4f6459]">
              {countryCode.toUpperCase()}
            </span>
            {totalPages > 1 && !searchQuery && filterType === "all" && (
              <span className="text-xs font-mono text-[#4f6459] border-l border-[rgba(34,229,122,.08)] pl-3">
                Page {currentPage} of {totalPages}
              </span>
            )}
          </div>
        </div>
      </motion.div>

      {/* Stats Row */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.05 }}
        className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3"
      >
        {firstEntry?.org && (
          <div className="bg-[#070b09]/60 border border-[rgba(34,229,122,.08)] rounded-lg p-3.5">
            <div className="flex items-center gap-2 text-[#6f8a7d] text-xs font-mono mb-1">
              <Building size={13} />
              Organization
            </div>
            <p className="font-medium text-sm truncate">{firstEntry.org}</p>
          </div>
        )}
        {firstEntry?.domain && (
          <div className="bg-[#070b09]/60 border border-[rgba(34,229,122,.08)] rounded-lg p-3.5">
            <div className="flex items-center gap-2 text-[#6f8a7d] text-xs font-mono mb-1">
              <Link2 size={13} />
              Domain
            </div>
            <p className="font-mono text-sm truncate text-[#7fe9ab]">
              {firstEntry.domain}
            </p>
          </div>
        )}
        <div className="bg-[#070b09]/60 border border-[rgba(34,229,122,.08)] rounded-lg p-3.5">
          <div className="flex items-center gap-2 text-[#6f8a7d] text-xs font-mono mb-1">
            <Shield size={13} />
            Networks
          </div>
          <p className="font-mono text-sm font-bold text-[#f2fff8]">
            {totalNetworks.toLocaleString()}
          </p>
        </div>
        <div className="bg-[#070b09]/60 border border-[rgba(34,229,122,.08)] rounded-lg p-3.5">
          <div className="flex items-center gap-2 text-[#6f8a7d] text-xs font-mono mb-1">
            <Filter size={13} />
            Filter
          </div>
          <div className="flex gap-1">
            {(["all", "IPv4", "IPv6"] as const).map((type) => (
              <button
                key={type}
                onClick={() => handleFilterChange(type)}
                className={`px-2.5 py-0.5 text-[10px] font-mono font-bold rounded-md transition-all duration-200 ${
                  filterType === type
                    ? type === "all"
                      ? "bg-[#22e57a] text-[#05100a]"
                      : type === "IPv4"
                        ? "bg-[#22e57a] text-[#05100a]"
                        : "bg-[#5c8aff] text-white"
                    : "bg-[#0a100d] text-[#4f6459] hover:text-[#6f8a7d] border border-[rgba(34,229,122,.06)]"
                }`}
              >
                {type === "all" ? "All" : type}
              </button>
            ))}
          </div>
        </div>
        <div className="bg-[#070b09]/60 border border-[rgba(34,229,122,.08)] rounded-lg p-3.5">
          <div className="flex items-center gap-2 text-[#6f8a7d] text-xs font-mono mb-1">
            <Download size={13} />
            Export
          </div>
          <div className="flex gap-1">
            {(["json", "txt", "csv"] as const).map((format) => (
              <button
                key={format}
                onClick={() => {
                  setDownloadFormat(format);
                  downloadNetworks();
                }}
                className={`px-2 py-0.5 text-[10px] font-mono font-bold rounded-md transition-all duration-200 flex items-center gap-1 ${
                  downloadFormat === format
                    ? "bg-[#22e57a] text-[#05100a]"
                    : "bg-[#0a100d] text-[#4f6459] hover:text-[#6f8a7d] border border-[rgba(34,229,122,.06)]"
                }`}
              >
                {format === "json" && <FileJson size={10} />}
                {format === "txt" && <FileText size={10} />}
                {format === "csv" && <FileSpreadsheet size={10} />}
                {format}
              </button>
            ))}
          </div>
        </div>
      </motion.div>

      {/* Search Bar */}
      <div className="relative">
        <div className="relative">
          <Search
            className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[#6f8a7d]"
            size={16}
          />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => handleSearch(e.target.value)}
            placeholder={`Search networks in AS${asn}...`}
            className="w-full bg-[#070b09]/60 border border-[rgba(34,229,122,.1)] rounded-xl pl-10 pr-10 py-3 text-sm text-[#c6d2ca] placeholder-[#4f6459] focus:outline-none focus:border-[rgba(34,229,122,.3)] focus:ring-1 focus:ring-[rgba(34,229,122,.15)] transition-all duration-200 font-mono"
          />
          {searchQuery && (
            <button
              onClick={clearSearch}
              className="absolute right-3.5 top-1/2 -translate-y-1/2 text-[#4f6459] hover:text-[#6f8a7d] transition-colors p-1 rounded-md hover:bg-[rgba(34,229,122,.06)]"
            >
              <X size={16} />
            </button>
          )}
        </div>
        {searchQuery && (
          <div className="mt-2 text-xs font-mono text-[#6f8a7d]">
            Found {filteredCount.toLocaleString()} network
            {filteredCount !== 1 ? "s" : ""} matching "{searchQuery}"
          </div>
        )}
      </div>

      {/* Networks List */}
      <div>
        <div className="flex items-center justify-between mb-3">
          <h2 className="text-sm font-mono font-bold text-[#6f8a7d] tracking-wider uppercase">
            Network Ranges
          </h2>
          <span className="text-xs font-mono text-[#4f6459]">
            {filteredCount.toLocaleString()} of {totalNetworks.toLocaleString()}
            {filterType !== "all" && ` (${filterType})`}
          </span>
        </div>

        <div className="grid grid-cols-1 gap-2">
          {currentData.length > 0 ? (
            currentData.map((entry, index) => {
              const globalIndex = startIndex + index;
              const ipVersion = detectIPVersion(entry.network);
              const isIPv4 = ipVersion === "IPv4";

              return (
                <motion.div
                  key={`${entry.network}-${index}`}
                  initial={{ opacity: 0, x: -10 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: index * 0.015 }}
                  className="group bg-[#070b09]/40 border border-[rgba(34,229,122,.06)] hover:border-[rgba(34,229,122,.15)] rounded-lg p-3 transition-all duration-300"
                >
                  <div className="flex items-center justify-between gap-3">
                    <div className="flex items-center gap-3 flex-1 min-w-0">
                      <span
                        className={`text-[10px] px-2 py-0.5 rounded font-mono font-bold flex-shrink-0 ${
                          isIPv4
                            ? "bg-[rgba(34,229,122,.08)] text-[#22e57a] border border-[rgba(34,229,122,.1)]"
                            : "bg-[rgba(92,138,255,.08)] text-[#5c8aff] border border-[rgba(92,138,255,.1)]"
                        }`}
                      >
                        {ipVersion}
                      </span>
                      <code className="text-sm font-mono text-[#7fe9ab] truncate">
                        {entry.network}
                      </code>
                    </div>
                    <div className="flex items-center gap-2 flex-shrink-0">
                      <span className="text-[10px] font-mono text-[#4f6459]">
                        {entry.country_code}
                      </span>
                      <button
                        onClick={() =>
                          copyToClipboard(entry.network, globalIndex)
                        }
                        className="p-1.5 rounded-md bg-[#0a100d] hover:bg-[rgba(34,229,122,.06)] transition-colors border border-[rgba(34,229,122,.06)] group"
                        aria-label="Copy network"
                      >
                        {copiedIndex === globalIndex ? (
                          <Check size={13} className="text-[#22e57a]" />
                        ) : (
                          <Copy
                            size={13}
                            className="text-[#4f6459] group-hover:text-[#6f8a7d]"
                          />
                        )}
                      </button>
                    </div>
                  </div>
                </motion.div>
              );
            })
          ) : (
            <div className="text-center py-12 bg-[#070b09]/40 border border-[rgba(34,229,122,.06)] rounded-lg">
              <p className="text-[#6f8a7d] font-mono text-sm">
                {filterType !== "all"
                  ? `No ${filterType} networks found`
                  : `No networks found matching "${searchQuery}"`}
              </p>
              <button
                onClick={() => {
                  clearSearch();
                  handleFilterChange("all");
                }}
                className="mt-3 text-[#22e57a] hover:text-[#5cffa5] transition-colors font-mono text-xs"
              >
                Clear all filters
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Pagination */}
      {totalPages > 1 && filteredCount > 0 && (
        <Pagination
          currentPage={currentPage}
          totalPages={totalPages}
          onPageChange={handlePageChange}
          className="mt-6"
        />
      )}

      {/* Results count */}
      {filteredCount > 0 && (
        <div className="text-center text-xs font-mono text-[#4f6459]">
          Showing {startIndex + 1} - {Math.min(endIndex, filteredCount)} of{" "}
          {filteredCount.toLocaleString()} networks
          {searchQuery && ` (filtered from ${totalNetworks.toLocaleString()})`}
          {filterType !== "all" && ` [${filterType}]`}
        </div>
      )}
    </div>
  );
}
